inputs.where:
@or(
  and(
    not(empty(item()?['templateGuid'])),
    equals(
      toLower(string(item()?['templateGuid'])),
      toLower(string(items('For_each_Activity_Template')?['gap_monitoringactivitytemplateid']))
    )
  ),
  and(
    not(empty(item()?['activityName'])),
    equals(
      toLower(trim(string(item()?['activityName']))),
      toLower(trim(string(items('For_each_Activity_Template')?['gap_name'])))
    )
  )
)

@and(
  equals(
    string(coalesce(item()?['questionType'], '')),
    string(coalesce(items('Apply_to_each_3')?['gap_type'], ''))
  ),
  equals(
    int(coalesce(item()?['questionOrder'], 0)),
    int(coalesce(items('Apply_to_each_3')?['gap_order'], 0))
  ),
  equals(
    string(coalesce(item()?['answers'], '')),
    string(coalesce(items('Apply_to_each_3')?['gap_choiceoptions'], ''))
  )
)
